<script lang="ts">
  import {language,translate,localMessage} from '../lib/language';
  import {tick,untrack,type Snippet} from 'svelte';
  import type {SocialState,WorldState,Ranking,HomeVisit} from '../lib/multiplayer';
  import WorldPanel from './WorldPanel.svelte';
  import {imageUrl} from '../lib/assets';
  let {social,connected,roomCode='',onsend,children,world,ranking,home,initialTab='rooms'}:{social:SocialState|null;connected:boolean;roomCode?:string;onsend:(packet:Record<string,unknown>)=>void;children:Snippet;world:WorldState|null;ranking:Ranking|null;home:HomeVisit|null;initialTab?:string}=$props();
  let tab=$state(untrack(()=>initialTab)),friendCode=$state(''),message=$state(''),copyStatus=$state('');
  let log=$state<HTMLDivElement|null>(null),followBottom=$state(true);
  $effect(()=>{if(roomCode)tab='rooms';});
  $effect(()=>{const messages=social?.chat,element=log;if(messages&&element&&followBottom)void tick().then(()=>element.scrollTop=element.scrollHeight);});
  async function copy(){try{await navigator.clipboard.writeText(social!.self.code);copyStatus='Kode disalin.';}catch{copyStatus='Pilih dan salin kode di atas.';}}
  function requestFriend(event:SubmitEvent){event.preventDefault();onsend({type:'friend_request',code:friendCode});}
  function chat(event:SubmitEvent){event.preventDefault();if(message.trim()){onsend({type:'chat',text:message});message='';}}
</script>

{#if social}
  <div class="social-profile"><span>{translate($language,"Kode temanmu","Your friend code")} <input aria-label={translate($language,'Kode temanmu','Your friend code')} readonly value={social.self.code}/></span><button class="small-button" onclick={copy}>{translate($language,"Salin","Copy")}</button><small>{social.onlineCount} {translate($language,"pemain online","players online")}</small></div>
  {#if copyStatus}<p class="copy-status" role="status">{localMessage($language,copyStatus)}</p>{/if}
{/if}
<nav class="social-tabs" aria-label={translate($language,'Area multiplayer','Multiplayer area')}>
  {#each [{id:'rooms',label:'Ruangan',icon:'room/joystick.png'},{id:'friends',label:'Teman',icon:'icons/phone/friends.png'},{id:'chat',label:'Chat publik',icon:'room/micro.png'},{id:'garden',label:'Kebun',icon:'decor/plant.svg'},{id:'ranking',label:'Peringkat',icon:'icons/phone/achievements.png'},{id:'home',label:'Rumah',icon:'decor/sofa.svg'}] as item}
    <button class:active={tab===item.id} aria-pressed={tab===item.id} disabled={item.id!=='rooms'&&!social} onclick={()=>tab=item.id}><img src={imageUrl(item.icon)} alt=""/>{({rooms:translate($language,'Ruangan','Room'),friends:translate($language,'Teman','Friends'),chat:translate($language,'Chat publik','Public chat'),garden:translate($language,'Kebun','Garden'),ranking:translate($language,'Peringkat','Leaderboard'),home:translate($language,'Rumah','Home')} as Record<string,string>)[item.id]}{item.id==='friends'&&social?.requests.length?` (${social.requests.length})`:''}</button>
  {/each}
</nav>

{#if tab==='rooms'}{@render children()}
{:else if tab==='friends'&&social}
  <h3>{translate($language,"Teman Pou","Pou friends")}</h3>
  <form class="friend-form" onsubmit={requestFriend}><label>{translate($language,"Kode teman","Friend code")}<input aria-label={translate($language,'Kode teman','Friend code')} maxlength="8" placeholder="A1B2C3D4" bind:value={friendCode} autocapitalize="characters" spellcheck="false"/></label><button class="small-button" disabled={!connected||friendCode.trim().length!==8}>{translate($language,"Tambah","Add")}</button></form>
  {#if social.requests.length}<h4>{translate($language,"Permintaan pertemanan","Friend requests")}</h4><ul class="friend-list">{#each social.requests as friend}<li><div><strong>{friend.name}</strong><small>{friend.code}</small></div><div class="friend-actions"><button class="small-button" onclick={()=>onsend({type:'friend_accept',target:friend.id})}>{translate($language,"Terima","Accept")}</button><button class="text-button" onclick={()=>onsend({type:'friend_decline',target:friend.id})}>{translate($language,"Tolak","Decline")}</button></div></li>{/each}</ul>{/if}
  <h4>{translate($language,"Daftar teman ·","Friends ·")} {social.friends.length}</h4>
  {#if !social.friends.length}<p>{translate($language,"Bagikan kode temanmu. Setelah permintaan diterima, kalian bisa saling mengundang bermain.","Share your friend code. Once accepted, you can invite each other to play.")}</p>{/if}
  <ul class="friend-list">{#each [...social.friends].sort((a,b)=>Number(b.online)-Number(a.online)) as friend}<li><div><strong><span class="presence" class:online={friend.online}></span>{friend.name}</strong><small>{friend.online?friend.room?translate($language,'Sedang di ruangan','In a room'):'Online':'Offline'} · {friend.code}</small></div><div class="friend-actions"><button class="small-button" disabled={!connected||!friend.online} onclick={()=>onsend({type:'invite',target:friend.id})}>{translate($language,"Undang","Invite")}</button><button class="small-button" onclick={()=>{onsend({type:'home_visit',target:friend.id});tab='home';}}>{translate($language,"Kunjungi","Visit")}</button><button class="text-button" aria-label={`${translate($language,'Hapus teman','Remove friend')} ${friend.name}`} onclick={()=>onsend({type:'friend_remove',target:friend.id})}>{translate($language,"Hapus","Remove")}</button></div></li>{/each}</ul>
{:else if tab==='chat'&&social}
  <h3>{translate($language,"Chat publik","Public chat")}</h3><p>{translate($language,"Ngobrol dengan pemain yang terhubung ke server ini.","Chat with players connected to this server.")}</p>
  <div class="chat-log" bind:this={log} onscroll={e=>followBottom=e.currentTarget.scrollHeight-e.currentTarget.scrollTop-e.currentTarget.clientHeight<36} role="log" aria-label={translate($language,'Chat publik','Public chat')} aria-relevant="additions" aria-atomic="false">
    {#if !social.chat.length}<p>{translate($language,"Belum ada pesan. Mulai percakapan!","No messages yet. Start the conversation!")}</p>{/if}
    {#each social.chat as entry(entry.id)}<article class:self={entry.author===social.self.id}><header><strong>{entry.name}{entry.author===social.self.id?translate($language,' (kamu)',' (you)'):''}</strong><time datetime={new Date(entry.at).toISOString()}>{new Date(entry.at).toLocaleTimeString($language==='id'?'id-ID':'en-US',{hour:'2-digit',minute:'2-digit'})}</time></header><p>{entry.text}</p></article>{/each}
  </div>
  <form class="chat-form" onsubmit={chat}><input aria-label={translate($language,'Pesan chat publik','Public chat message')} maxlength="240" placeholder={translate($language,'Tulis pesan…','Write a message…')} bind:value={message} autocomplete="off"/><button class="small-button" disabled={!connected||!message.trim()}>{translate($language,"Kirim","Send")}</button></form><small class="message-count">{message.length}/240</small>
{:else if social&&['garden','ranking','home'].includes(tab)}<WorldPanel mode={tab} {social} {world} {ranking} {home} {onsend}/>{/if}

<style>
  .social-profile{display:flex;align-items:center;gap:8px;flex-wrap:wrap;text-align:left;padding:10px 12px;border:1.5px solid #b8aa7d;border-radius:12px;background:#fff7dc;margin-bottom:12px;font:13px/1.4 system-ui,sans-serif}.social-profile span{flex:1}.social-profile input{display:block;width:130px;border:0;background:none;padding:2px 0;color:#35382f;font:700 20px/1.4 monospace}.social-profile small{width:100%;color:#5a6950}.social-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:12px 0 20px}.social-tabs button{display:flex;flex-direction:column;align-items:center;gap:4px;border:2px solid #bbaf85;border-radius:12px;background:#fff4d3;padding:8px 4px;font-size:17px;min-height:70px;color:#373a30}.social-tabs button.active{border-color:#607b46;background:#d5eeb2}.social-tabs img{width:30px;height:30px}.social-tabs button:disabled{opacity:.5}.small-button{border:2px solid #596742;border-radius:9px;background:#d2eaa7;color:#303629;padding:9px 13px;font:600 14px/1.2 system-ui,sans-serif;min-height:42px;white-space:nowrap}.small-button:disabled{opacity:.45}.text-button{border:0;background:none;text-decoration:underline;color:#6a5146;padding:8px;font:13px/1.3 system-ui,sans-serif;min-height:40px}h3{font-size:25px;font-weight:400;margin:10px 0}h4{font-size:19px;font-weight:400;text-align:left;margin:18px 0 6px}.friend-form,.chat-form{display:flex;gap:8px;align-items:end;margin:12px 0}.friend-form label{flex:1;text-align:left;font:14px/1.4 system-ui,sans-serif}.friend-form input,.chat-form input{display:block;width:100%;min-width:0;border:2px solid #aa9d74;border-radius:8px;padding:10px;background:#fffbee;font:16px/1.3 system-ui,sans-serif;margin-top:5px}.chat-form input{flex:1}.friend-list{list-style:none;padding:0;margin:0}.friend-list li{display:flex;justify-content:space-between;align-items:center;gap:8px;text-align:left;padding:12px 0;border-bottom:1px solid #c4b992}.friend-list strong{font-size:19px;font-weight:400;overflow-wrap:anywhere}.friend-list small{display:block;font:12px/1.5 system-ui,sans-serif;color:#615f50}.friend-actions{display:flex;flex-direction:column;align-items:center}.presence{display:inline-block;width:9px;height:9px;border:1px solid #777564;border-radius:50%;background:#b7b5a8;margin-right:7px}.presence.online{background:#7db86c;border-color:#48753d}.chat-log{height:clamp(180px,30dvh,330px);overflow-y:auto;overscroll-behavior:contain;background:#e8e4cb;border:1.5px solid #c0b589;border-radius:12px;padding:12px;text-align:left}.chat-log article{background:#fff9e7;border:1px solid #c6b994;border-radius:12px;padding:9px 12px;margin-bottom:10px;overflow-wrap:anywhere}.chat-log article.self{background:#dfefc8;border-color:#91ae77}.chat-log header{display:flex;align-items:center;justify-content:space-between;gap:12px;font:600 13px/1.4 system-ui,sans-serif}.chat-log time{font-size:11px;font-weight:400;white-space:nowrap;color:#686854}.chat-log article p{font:15px/1.45 system-ui,sans-serif;white-space:pre-wrap;margin:5px 0 0}.message-count{display:block;text-align:right;font:12px/1.4 system-ui,sans-serif;color:#77745f}.copy-status{font-size:12px!important}
</style>
